.relaxation-options{display:flex;gap:14px;flex-wrap:wrap;font-size:13px;margin-bottom:18px}.relaxation-options label{display:flex;gap:6px;align-items:center}.relaxation-options input{width:100px;padding:8px;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--text)}.relaxation-options .hint{width:100%;margin:0}
details{font-size:13px;color:var(--muted);margin:12px 0;line-height:1.6}details p{font-size:13px;overflow-wrap:anywhere}summary{cursor:pointer}.structure-summary>.secondary-button{margin-top:12px}
.selection-exclusions{max-height:360px;overflow:auto;border:1px solid var(--line);border-radius:8px;padding:12px;margin:14px 0}.selection-exclusions article{border-bottom:1px solid var(--line);padding:10px 0}.selection-exclusions p{margin:4px 0}.selection-exclusions code{font-size:11px;color:var(--muted)}
